func LoadTargets(root string) (Targets, error) {
	var targets Targets
	if err := decode(filepath.Join(root, "targets.yaml"), &targets); err != nil {
		return targets, err
	}
	if targets.Version != 1 || len(targets.Languages) == 0 {
		return targets, fmt.Errorf("invalid generation targets")
	}
	for language, group := range targets.Languages {
		if language == "" || len(group.Targets) == 0 {
			return targets, fmt.Errorf("invalid generation targets for %q", language)
		}
		seen := map[string]bool{}
		for _, target := range group.Targets {
			// Provider targets may reuse the shared client descriptor as source;
			// uniqueness is per output directory.
			key := target.Source + "\x00" + target.Output
			if target.Source == "" || target.Output == "" || target.Module == "" || filepath.IsAbs(target.Source) || filepath.IsAbs(target.Output) || seen[key] {
				return targets, fmt.Errorf("invalid or duplicate %s target %q -> %q", language, target.Source, target.Output)
			}
			if target.Provider != "" && (strings.TrimSpace(target.Provider) != target.Provider || strings.ContainsAny(target.Provider, "/\\")) {
				return targets, fmt.Errorf("invalid %s provider name %q", language, target.Provider)
			}
			seen[key] = true
		}
	}
	return targets, nil
}

// ProviderNames returns unique provider identities declared on generation targets.
func (t Targets) ProviderNames() []string {
	seen := map[string]bool{}
	var names []string
	for _, group := range t.Languages {
		for _, target := range group.Targets {
			if target.Provider == "" || seen[target.Provider] {
				continue
			}
			seen[target.Provider] = true
			names = append(names, target.Provider)
		}
	}
	return names
}

