// Package goemit dispatches compiled generation phases to native Go emitters.
package goemit

import (
	"fmt"
	"path"
	"strings"

	codegen "github.com/sandbox-kit/kit/tooling/internal/gen/codegen/v1"
	declarationgen "github.com/sandbox-kit/kit/tooling/internal/go/declaration_gen"
	mappinggen "github.com/sandbox-kit/kit/tooling/internal/go/mapping_gen"
	providergen "github.com/sandbox-kit/kit/tooling/internal/go/provider_gen"
	typesgen "github.com/sandbox-kit/kit/tooling/internal/go/types_gen"
	validationgen "github.com/sandbox-kit/kit/tooling/internal/go/validation_gen"
	"github.com/sandbox-kit/kit/tooling/internal/model"
	"github.com/sandbox-kit/kit/tooling/internal/spec"
	"google.golang.org/protobuf/compiler/protogen"
	"google.golang.org/protobuf/proto"
)

// Generate consumes a language-neutral program. Only this layer chooses Go
// bindings, native naming, imports, and output file conventions.
// provider selects provider emission when non-empty (from specs/targets.yaml).
func Generate(plugin *protogen.Plugin, file *protogen.File, program *model.Program, providerName string) error {
	profile, err := spec.LoadLanguageProfile("specs", "go")
	if err != nil {
		return err
	}
	if err := declarationgen.ValidateProfile(profile); err != nil {
		return err
	}
	var phases []string
	rules := spec.Validation{}
	root := "CreateOptions"
	var provider model.Provider
	switch {
	case providerName != "":
		providerName = strings.TrimSpace(providerName)
		var ok bool
		provider, ok = program.Providers[providerName]
		if !ok {
			return fmt.Errorf("%s: unknown provider %q", file.Desc.Path(), providerName)
		}
		phases = program.Generation.Provider
	case file.Desc.Path() == "kit/sandbox/v1/sandbox.proto":
		phases = program.Generation.Shared
		rules = program.Validation
	case proto.HasExtension(file.Desc.Options(), codegen.E_Client):
		phases = program.Generation.Client
		rules = program.Client.Validation
		root = program.Client.ConfigMessage
	default:
		return fmt.Errorf("%s: unsupported Go generation target", file.Desc.Path())
	}
	for _, phase := range phases {
		var err error
		switch phase {
		case "diagnostic_paths":
			err = typesgen.GenerateErrorPaths(plugin, file)
		case "field_paths":
			err = typesgen.GeneratePaths(plugin, file, program.Templates, profile)
		case "validation":
			err = validationgen.Generate(plugin, file, rules, root, program.Templates, profile)
		case "checks":
			err = providergen.GenerateChecks(plugin, file, provider.Rules, program.Templates, profile)
		case "mappings":
			err = mappinggen.Generate(plugin, file, provider, program.Templates, profile)
		default:
			return fmt.Errorf("unsupported Go emission phase %s", phase)
		}
		if err != nil {
			return fmt.Errorf("%s: %s: %w", file.Desc.Path(), phase, err)
		}
	}
	return nil
}

// ProviderFilenamePrefix is the generated-file stem for provider helpers.
// Provider targets may reuse client.proto as the descriptor input while still
// emitting provider.*.gen.go beside the handwritten adapter.
func ProviderFilenamePrefix(file *protogen.File) string {
	return path.Join(path.Dir(file.GeneratedFilenamePrefix), "provider")
}

// Package typescriptemit dispatches the language-neutral program to TypeScript emitters.
package typescriptemit

import (
	"fmt"
	"strings"

	codegen "github.com/sandbox-kit/kit/tooling/internal/gen/codegen/v1"
	"github.com/sandbox-kit/kit/tooling/internal/model"
	"github.com/sandbox-kit/kit/tooling/internal/spec"
	declarationgen "github.com/sandbox-kit/kit/tooling/internal/typescript/declaration_gen"
	providergen "github.com/sandbox-kit/kit/tooling/internal/typescript/provider_gen"
	"google.golang.org/protobuf/compiler/protogen"
	"google.golang.org/protobuf/proto"
)

// Generate emits one TypeScript source file for a declared generation target.
// provider selects provider emission when non-empty (from specs/targets.yaml).
func Generate(plugin *protogen.Plugin, file *protogen.File, program *model.Program, providerName string) error {
	profile, err := spec.LoadLanguageProfile("specs", "typescript")
	if err != nil {
		return err
	}
	if err := declarationgen.ValidateProfile(profile); err != nil {
		return err
	}
	var phases []string
	providerName = strings.TrimSpace(providerName)
	switch {
	case providerName != "":
		if _, ok := program.Providers[providerName]; !ok {
			return fmt.Errorf("%s: unknown provider %q", file.Desc.Path(), providerName)
		}
		phases = program.Generation.Provider
	case file.Desc.Path() == "kit/sandbox/v1/sandbox.proto":
		phases = program.Generation.Shared
	case proto.HasExtension(file.Desc.Options(), codegen.E_Client):
		phases = program.Generation.Client
	default:
		return fmt.Errorf("%s: unsupported TypeScript generation target", file.Desc.Path())
	}
	for _, phase := range phases {
		var phaseErr error
		switch phase {
		case "mappings":
			switch providerName {
			case "daytona":
				phaseErr = generateDaytonaMappings(plugin, file, program.Providers[providerName])
			case "modal":
				phaseErr = generateModalMappings(plugin, file, program.Providers[providerName])
			default:
				phaseErr = fmt.Errorf("unsupported TypeScript provider %s", providerName)
			}
		case "checks":
			if providerName != "" {
				phaseErr = providergen.GenerateChecks(plugin, file, program.Providers[providerName].Rules, program.Schema)
			}
		case "configuration":
			if providerName != "" {
				phaseErr = providergen.GenerateConfig(plugin, file, program.Providers[providerName].Rules, program.Schema)
			}
		case "diagnostic_paths", "field_paths", "validation":
			// Shared/client TypeScript validation and path tables are not emitted yet;
			// Go owns those helpers. Phases remain listed so omissions stay explicit.
		default:
			return fmt.Errorf("%s: unsupported TypeScript emission phase %s", file.Desc.Path(), phase)
		}
		if phaseErr != nil {
			return fmt.Errorf("%s: %s: %w", file.Desc.Path(), phase, phaseErr)
		}
	}
	return nil
}

package spec

import (
	"fmt"
	"path/filepath"
)

// Generation selects semantic output phases, independent of language syntax.
type Generation struct {
	Version  int      `yaml:"version"`
	Shared   []string `yaml:"shared"`
	Client   []string `yaml:"client"`
	Provider []string `yaml:"provider"`
}

func LoadGeneration(root string) (Generation, error) {
	var result Generation
	if err := decode(filepath.Join(root, "generation.yaml"), &result); err != nil {
		return result, err
	}
	if result.Version != 1 {
		return result, fmt.Errorf("unsupported generation version %d", result.Version)
	}
	roles := []struct {
		name    string
		phases  []string
		allowed []string
	}{
		{"shared", result.Shared, []string{"diagnostic_paths", "field_paths", "validation"}},
		{"client", result.Client, []string{"diagnostic_paths", "field_paths"}},
		{"provider", result.Provider, []string{"checks", "mappings"}},
	}
	for _, role := range roles {
		if len(role.phases) != len(role.allowed) {
			return result, fmt.Errorf("%s: missing generation phase", role.name)
		}
		seen := map[string]bool{}
		for _, phase := range role.phases {
			valid := false
			for _, allowed := range role.allowed {
				if phase == allowed {
					valid = true
				}
			}
			if !valid || seen[phase] {
				return result, fmt.Errorf("%s: unknown or duplicate phase %q", role.name, phase)
			}
			seen[phase] = true
		}
	}
	return result, nil
}

package spec

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestGenerationRejectsUnsupportedOrUnsafePlans(t *testing.T) {
	body, err := os.ReadFile(filepath.Join("..", "..", "..", "specs", "generation.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct{ name, old, new string }{
		{"unknown phase", "shared: [diagnostic_paths, field_paths, validation]", "shared: [diagnostic_paths, field_paths, arbitrary_code]"},
		{"missing phase", "shared: [diagnostic_paths, field_paths, validation]", "shared: [diagnostic_paths, validation]"},
		{"duplicate phase", "shared: [diagnostic_paths, field_paths, validation]", "shared: [diagnostic_paths, field_paths, field_paths]"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			root := t.TempDir()
			if err := os.WriteFile(filepath.Join(root, "generation.yaml"), []byte(strings.Replace(string(body), tc.old, tc.new, 1)), 0600); err != nil {
				t.Fatal(err)
			}
			if _, err := LoadGeneration(root); err == nil {
				t.Fatal("invalid generation plan accepted")
			}
		})
	}
}

func TestGenerationLoadsPhasePlan(t *testing.T) {
	plan, err := LoadGeneration(filepath.Join("..", "..", "..", "specs"))
	if err != nil {
		t.Fatal(err)
	}
	if len(plan.Shared) == 0 || len(plan.Client) == 0 || len(plan.Provider) == 0 {
		t.Fatal("expected shared, client, and provider phases")
	}
}

